use xiom.io;
interface Comparable {
  fn is_greater(&self, other: &Self) -> Bool;
}

type Player {
  name: Str;
  score: Int;
}

fn Player.is_greater(&self, other: &Player) -> Bool {
  self.score > other.score
}

fn sort[T: Comparable](items: &mut Vec[T]) {
  let mut i = 0;
  while i < items.len() {
    let mut j = i + 1;
    while j < items.len() {
      if items.get(i).unwrap().is_greater(items.get(j).unwrap()) {
        let a = items.get(i).unwrap().clone();
        let b = items.get(j).unwrap().clone();
        items.set(i, b);
        items.set(j, a);
      }
      j += 1;
    }
    i += 1;
  }
}

fn main() -> Int {
  let mut players: Vec[Player] = Vec[Player].new();
  players.push(Player{ name: "Alex", score: 85 });
  players.push(Player{ name: "Blake", score: 92 });
  players.push(Player{ name: "Casey", score: 73 });
  sort(&mut players);
  let mut k = 0;
  while k < players.len() {
    io.println(players.get(k).unwrap().score.to_str());
    k += 1;
  }
  return 0;
}
